const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const rawWhen = typeof $json.when === 'string' ? $json.when.trim().toLowerCase() : '';
const rawFilter = typeof $json.filter === 'string' ? $json.filter.trim().toLowerCase() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'The report request needs a valid conversation and request ID.' };
}
const when = ['latest', 'week'].includes(rawWhen) ? rawWhen : 'latest';
const filter = ['open', 'closing', 'all'].includes(rawFilter) ? rawFilter : 'open';
const proposedInput = { sessionId, requestId, when, filter };
return { json: { valid: error === null, ...proposedInput, proposedInput, ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Report Input').first().json;
const runRows = $('Read Latest Run').all().map((item) => item.json).filter((row) => row && row.ranAt);
const rows = $input.all().map((item) => item.json).filter((row) => row && row.fingerprint);

if (runRows.length === 0) {
  return [{ json: { ...input, response: {
    ok: true,
    hasRun: false,
    message: 'The funding scan has not produced a report yet. It runs every morning at 8. If it has never run, the 71 - TRIGGER workflow may still be switched off in n8n.'
  } } }];
}

const latest = runRows[0];
const dayIndex = (value) => {
  const text = String(value ?? '').trim();
  const isoDate = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoDate) return Math.floor(Date.UTC(Number(isoDate[1]), Number(isoDate[2]) - 1, Number(isoDate[3])) / 86400000);
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return null;
  return Math.floor(Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate()) / 86400000);
};
const todayIndex = dayIndex(new Date());
const daysUntil = (value) => {
  if (!value) return null;
  const index = dayIndex(value);
  return index === null ? null : index - todayIndex;
};

const live = rows.filter((row) => String(row.dismissed ?? '') !== 'yes');
const chosen = live.filter((row) => {
  if (input.filter === 'all') return true;
  const left = daysUntil(row.closesAt);
  if (input.filter === 'closing') return left !== null && left >= 0 && left <= 14;
  return String(row.status ?? '') !== 'closed' && (left === null || left >= 0);
});

chosen.sort((a, b) => {
  const leftA = daysUntil(a.closesAt);
  const leftB = daysUntil(b.closesAt);
  if (leftA === null && leftB === null) return 0;
  if (leftA === null) return 1;
  if (leftB === null) return -1;
  return leftA - leftB;
});

const opportunities = chosen.slice(0, 25).map((row) => ({
  programName: row.programName,
  administeredBy: row.administeredBy,
  amountText: row.amountText,
  closesAt: row.closesAt,
  daysLeft: daysUntil(row.closesAt),
  status: row.status,
  verdict: row.verdict,
  verdictReason: row.verdictReason,
  deciderCriterion: row.deciderCriterion,
  sourceTrust: row.sourceTrust,
  officialUrl: row.officialUrl,
}));

return [{ json: { ...input, response: {
  ok: true,
  hasRun: true,
  ranAt: latest.ranAt,
  runStatus: latest.status,
  reportText: String(latest.reportText ?? ''),
  totalTracked: live.length,
  count: opportunities.length,
  filter: input.filter,
  opportunities,
  message: 'This is the saved morning report. It was written by the scheduled scan; nothing was researched to answer this question.'
} } }];

const input = $('Validate Report Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'get_funding_report',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
